// Copies Mozilla PDF.js (pdfjs-dist, legacy build for older Android WebViews) into
// src/generated/pdfjs-source.ts as two strings, so the in-app PDF viewer works offline.
// Runs after `npm install` (postinstall); the generated file is git-ignored.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const build = join(root, 'node_modules', 'pdfjs-dist', 'legacy', 'build');
const lib = readFileSync(join(build, 'pdf.min.mjs'), 'utf8');
const worker = readFileSync(join(build, 'pdf.worker.min.mjs'), 'utf8');

// Both are placed inside <script type="text/plain"> elements, which a "</script" would end early.
for (const [name, code] of [['pdf.min.mjs', lib], ['pdf.worker.min.mjs', worker]]) {
  if (code.includes('</script')) throw new Error(`${name} contains "</script" and can't be embedded`);
}

const out = join(root, 'src', 'generated', 'pdfjs-source.ts');
mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  `// Generated by scripts/build-pdfjs-source.mjs from pdfjs-dist. Do not edit.\n` +
    `export const PDFJS_LIB = ${JSON.stringify(lib)};\n` +
    `export const PDFJS_WORKER = ${JSON.stringify(worker)};\n`,
);
console.log(`pdfjs: wrote ${out} (${Math.round((lib.length + worker.length) / 1024)} KB)`);
